{
  "name": "Keithley 2400 / Lake Shore 350 联合实验控制组件",
  "name_en": "Keithley 2400 / Lake Shore 350 Experiment Control Component",
  "manufacturer": "",
  "description": "一个非物理软件组件，用于协调 Keithley 2400 源表与 Lake Shore 350 温控器的实验流程。它负责仪器连接、参数配置、温度读取、加热器量程与温度设定值设置、温度斜坡控制、电学测量读取，以及实验图形界面的创建、样式、日志和状态管理。",
  "description_en": "A non-physical software component that coordinates experiments involving a Keithley 2400 source meter and a Lake Shore 350 temperature controller. It handles instrument connection, configuration, temperature readback, heater-range and setpoint control, temperature ramping, electrical measurement readout, and GUI creation, styling, logging, and UI state management.",
  "actions": [
    {
      "action_name": "auto-configure_instruments",
      "description": "配置 Keithley 2400 的源表参数以及 Lake Shore 350 的温控参数。",
      "description_en": "Configure the Keithley 2400 source/measurement settings and the Lake Shore 350 temperature-control settings."
    },
    {
      "action_name": "auto-connect",
      "description": "连接到 Keithley 2400 和 Lake Shore 350 仪器。",
      "description_en": "Connect to the Keithley 2400 and Lake Shore 350 instruments."
    },
    {
      "action_name": "auto-set_heater_range",
      "description": "设置指定输出通道的加热器量程。",
      "description_en": "Set the heater range for the selected output channel."
    },
    {
      "action_name": "auto-set_setpoint",
      "description": "设置指定输出通道的温度设定值。",
      "description_en": "Set the temperature setpoint for the selected output channel."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭实验控制流程并执行相关仪器的安全停机。",
      "description_en": "Shut down the experiment control flow and perform a safe stop of the associated instruments."
    },
    {
      "action_name": "auto-start_ramp",
      "description": "以指定速率启动到目标温度的斜坡控制。",
      "description_en": "Start a temperature ramp to the target temperature at the specified rate."
    },
    {
      "action_name": "auto-get_measurement",
      "description": "获取电学测量值。",
      "description_en": "get electrical measurement reading"
    },
    {
      "action_name": "auto-get_temperature",
      "description": "获取温度。",
      "description_en": "get temperature"
    },
    {
      "action_name": "auto-setup_styles",
      "description": "配置图形界面的样式。",
      "description_en": "Set up the GUI styles."
    },
    {
      "action_name": "auto-create_widgets",
      "description": "创建图形界面控件。",
      "description_en": "Create the GUI widgets."
    },
    {
      "action_name": "auto-log",
      "description": "记录实验或界面日志信息。",
      "description_en": "Log experiment or UI messages."
    },
    {
      "action_name": "auto-start_experiment",
      "description": "启动联动温控与测量实验流程。",
      "description_en": "Start the coordinated temperature-control and measurement experiment."
    },
    {
      "action_name": "auto-stop_experiment",
      "description": "停止联动温控与测量实验流程。",
      "description_en": "Stop the coordinated temperature-control and measurement experiment."
    },
    {
      "action_name": "auto-set_ui_state",
      "description": "设置界面的启用或禁用状态。",
      "description_en": "Set the enabled or disabled state of the user interface."
    }
  ],
  "tag_hints": [
    "Keithley 2400",
    "Lake Shore 350",
    "temperature control",
    "temperature ramping",
    "heater range control",
    "SMU measurement",
    "experiment GUI"
  ]
}

